BEGIN
    EXECUTE format(
        'SELECT owner_decision, source_binding_version FROM %I.ingress_messages WHERE message_key = $1 FOR UPDATE',
        TG_TABLE_SCHEMA
    ) INTO source_decision, source_binding_version USING NEW.source_message_key;
