CREATE FUNCTION pubsub_runtime_attach_lock()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$    LOCK TABLE "public"."dnd_projection" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."dnd_projection_source_version" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."notification_settings_projection" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."notification_settings_projection_source_version" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_affiliations" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_items" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_nodes" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_owner_configured" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_push_publications" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_schema_marker" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_schema_version" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
    LOCK TABLE "public"."pubsub_subscriptions" IN SHARE UPDATE EXCLUSIVE MODE NOWAIT;
SELECT NULL::void;$function$;

